"""Follow-up suggestions derived from the actual result (not generated by the LLM)."""

from __future__ import annotations

from app.agent.schemas import Evidence, ParsedQuestion

DEFAULT_SUGGESTIONS = [
    "Which region has the highest revenue?",
    "Which region grew fastest?",
    "What are the top 5 products?",
    "How did revenue change between 2011-Q2 and 2011-Q3?",
    "Which customer segment is most valuable?",
    "What is the largest sales anomaly?",
    "Did the clearance campaign coincide with higher sales?",
    "Forecast revenue for the next 30 days",
    "Is the difference between Western Europe and Northern Europe statistically significant?",
]


def focus_of(pq: ParsedQuestion, ev: Evidence) -> tuple[str | None, str | None]:
    h = ev.headline
    if ev.status != "answered":
        return None, None
    if pq.intent == "growth_ranking" and h.get("dimension") in ("region", "country"):
        return h.get("fastest"), h["dimension"]
    if pq.intent == "revenue_ranking" and h.get("dimension") in ("region", "country"):
        return h.get("leader"), h["dimension"]
    if pq.intent == "period_change" and h.get("largest_region_contributor"):
        return h["largest_region_contributor"], "region"
    if pq.intent == "drivers":
        for f in pq.filters:
            if f.dimension in ("region", "country"):
                return f.values[0], f.dimension
    return None, None


def suggest(pq: ParsedQuestion, ev: Evidence) -> list[str]:
    h, i = ev.headline, pq.intent
    if ev.status != "answered":
        return DEFAULT_SUGGESTIONS[:3]
    out: list[str] = []
    if i == "revenue_ranking" and h.get("dimension") == "region":
        out.append(f"Show the monthly revenue trend for {h['leader']}")
        if h.get("runner_up"):
            out.append(f"Compare {h['leader']} and {h['runner_up']}")
        out.append("Which region grew fastest?")
    elif i == "revenue_ranking":
        out += ["Which region grew fastest?", "What are the top 5 products?"]
    elif i == "growth_ranking":
        if h.get("fastest"):
            out.append("What products drove that growth?")
            out.append(f"Show the monthly revenue trend for {h['fastest']}")
        if h.get("second") and h.get("dimension") in ("region", "country"):
            out.append(f"Compare {h['fastest']} and {h['second']}")
    elif i == "top_products":
        out += ["How did revenue change between 2011-Q2 and 2011-Q3?", "Which customer segment is most valuable?"]
    elif i == "period_change":
        if h.get("largest_region_contributor"):
            out.append("What products drove that change?")
        out.append("Which region grew fastest?")
        out.append("Show the monthly revenue trend")
    elif i == "drivers":
        if h.get("filter"):
            out.append(f"Show the monthly revenue trend for {h['filter'].split('=')[1]}")
        out.append("What is the largest sales anomaly?")
    elif i == "trend":
        out += ["What is the largest sales anomaly?", "Forecast revenue for the next 30 days"]
    elif i == "segment_value":
        out += ["What are the top 5 products?", "Which region has the highest revenue?"]
    elif i == "anomaly":
        d = h.get("date", "")
        if d:
            out.append(f"How did revenue change between {_prev_month(d)} and {d[:7]}?")
        out.append("Show the monthly revenue trend")
    elif i == "campaign_effect":
        out += ["Show the monthly revenue trend", "Is the difference between Western Europe and Northern Europe statistically significant?"]
    elif i == "forecast":
        out += ["What is the largest sales anomaly?", "Show the monthly revenue trend"]
    elif i in ("compare_groups", "association", "correlation"):
        out += ["Is product category mix associated with region?" if i != "association" else "Which region has the highest revenue?",
                "What are the top 5 products?"]
    return out[:3]


def _prev_month(d: str) -> str:
    y, m = int(d[:4]), int(d[5:7])
    return f"{y}-{m - 1:02d}" if m > 1 else f"{y - 1}-12"
